def bfs_at_depth(graph, start, target_depth):
    visited = set()
    queue = deque([(start, 0)])  # (node, depth)
    depth_nodes = {}  # depth -> set of nodes

    while queue:
        node, depth = queue.popleft()

        if node in visited:
            continue
        visited.add(node)

        # Record node at its depth
        if depth not in depth_nodes:
            depth_nodes[depth] = set()
        depth_nodes[depth].add(node)

        # Add neighbors to queue with incremented depth
        if node in graph:
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, depth + 1))

    return depth_nodes.get(target_depth, set())

